import { h, type VNodeChild } from "vue";

export type TrainingFormState = Record<string, unknown>;

export type TrainingVisibilityRule<TForm extends TrainingFormState = TrainingFormState> =
  | ((form: TForm) => boolean)
  | {
      key: keyof TForm & string;
      equals?: unknown;
      notEquals?: unknown;
      truthy?: boolean;
    };

interface TrainingFieldBase<TForm extends TrainingFormState> {
  key: keyof TForm & string;
  id: string;
  label: string;
  description?: string;
  hidden?: boolean;
  disabled?: boolean;
  visibleWhen?: TrainingVisibilityRule<TForm>;
  role?: "file" | "folder" | "table" | "slider" | "switch";
}

export type TrainingFieldSpec<TForm extends TrainingFormState = TrainingFormState> =
  | (TrainingFieldBase<TForm> & {
      kind: "text";
      placeholder?: string;
    })
  | (TrainingFieldBase<TForm> & {
      kind: "number";
      min?: number;
      max?: number;
      step?: string | number;
    })
  | (TrainingFieldBase<TForm> & {
      kind: "checkbox";
    })
  | (TrainingFieldBase<TForm> & {
      kind: "select";
      options: string[];
    })
  | (TrainingFieldBase<TForm> & {
      kind: "textarea";
      rows?: number;
    })
  | (TrainingFieldBase<TForm> & {
      kind: "table";
      addLabel?: string;
    });

export interface RunControl {
  label: string;
  onClick: () => void | Promise<void>;
  primary?: boolean;
}

export type TrainingSectionItem<TForm extends TrainingFormState = TrainingFormState> =
  | TrainingFieldSpec<TForm>
  | {
      kind: "row";
      fields: TrainingFieldSpec<TForm>[];
      hidden?: boolean;
      visibleWhen?: TrainingVisibilityRule<TForm>;
    };

export interface TrainingSectionSpec<TForm extends TrainingFormState = TrainingFormState> {
  title: string;
  fields: TrainingSectionItem<TForm>[];
  hidden?: boolean;
  visibleWhen?: TrainingVisibilityRule<TForm>;
}

export interface TrainingPathBrowseDetail {
  key: string;
  role: "file" | "folder";
  id: string;
}

export function defineTrainingField<TForm extends TrainingFormState>(field: TrainingFieldSpec<TForm>) {
  return field;
}

export function defineTrainingRow<TForm extends TrainingFormState>(
  fields: TrainingFieldSpec<TForm>[],
  options: Omit<Extract<TrainingSectionItem<TForm>, { kind: "row" }>, "kind" | "fields"> = {},
) {
  return { kind: "row" as const, fields, ...options };
}

export function defineTrainingSection<TForm extends TrainingFormState>(
  title: string,
  fields: TrainingSectionItem<TForm>[],
  options: Omit<TrainingSectionSpec<TForm>, "title" | "fields"> = {},
) {
  return { title, fields, ...options };
}

export function defineTrainingSections<TForm extends TrainingFormState>(sections: TrainingSectionSpec<TForm>[]) {
  return sections;
}

export function installTrainingPathBrowseBridge(onBrowse: (detail: TrainingPathBrowseDetail) => void) {
  const listener = (event: Event) => {
    const detail = (event as CustomEvent<TrainingPathBrowseDetail>).detail;
    if (!detail?.key || (detail.role !== "file" && detail.role !== "folder")) {
      return;
    }
    onBrowse(detail);
  };
  window.addEventListener("sd-training-path-browse", listener);
  return () => window.removeEventListener("sd-training-path-browse", listener);
}

export function renderTrainingField<TForm extends TrainingFormState>(form: TForm, field: TrainingFieldSpec<TForm>) {
  if (field.hidden || !matchesVisibilityRule(form, field.visibleWhen)) {
    return null;
  }

  if (field.kind === "checkbox") {
    return h("label", { class: "training-toggle anima-toggle" }, [
      h("input", {
        id: field.id,
        type: "checkbox",
        disabled: field.disabled,
        checked: Boolean(form[field.key]),
        onChange: (event: Event) => {
          form[field.key] = (event.target as HTMLInputElement).checked as TForm[keyof TForm & string];
        },
      }),
      h("span", field.label),
      renderFieldDescription(field.description),
    ]);
  }

  if (field.kind === "select") {
    return h("label", { class: "training-field anima-field" }, [
      h("span", field.label),
      h(
        "select",
        {
          id: field.id,
          disabled: field.disabled,
          value: String(form[field.key] ?? ""),
          onChange: (event: Event) => {
            form[field.key] = (event.target as HTMLSelectElement).value as TForm[keyof TForm & string];
          },
        },
        field.options.map((value) => h("option", { value }, value || "auto")),
      ),
      renderFieldDescription(field.description),
    ]);
  }

  if (field.kind === "textarea") {
    return h("label", { class: "training-field anima-field" }, [
      h("span", field.label),
      h("textarea", {
        id: field.id,
        disabled: field.disabled,
        value: String(form[field.key] ?? ""),
        rows: field.rows ?? 4,
        onInput: (event: Event) => {
          form[field.key] = (event.target as HTMLTextAreaElement).value as TForm[keyof TForm & string];
        },
      }),
      renderFieldDescription(field.description),
    ]);
  }

  if (field.kind === "number") {
    if (field.role === "slider") {
      return renderSliderField(form, field);
    }
    return h("label", { class: "training-field anima-field" }, [
      h("span", field.label),
      h("input", {
        id: field.id,
        type: "number",
        min: field.min ?? 0,
        max: field.max,
        step: field.step ?? 1,
        disabled: field.disabled,
        value: Number(form[field.key] ?? 0),
        onInput: (event: Event) => {
          form[field.key] = Number((event.target as HTMLInputElement).value) as TForm[keyof TForm & string];
        },
      }),
      renderFieldDescription(field.description),
    ]);
  }

  if (field.kind === "table") {
    return renderTrainingTableField(form, field);
  }

  return h("label", { class: "training-field anima-field" }, [
    h("span", field.label),
    renderTextInput(form, field),
    renderFieldDescription(field.description),
  ]);
}

export function renderTrainingFields<TForm extends TrainingFormState>(
  form: TForm,
  fields: TrainingFieldSpec<TForm>[],
) {
  return fields.map((field) => renderTrainingField(form, field));
}

export function renderTrainingFieldRow(children: VNodeChild[]) {
  return h("div", { class: "training-field-row anima-field-row" }, children);
}

export function sectionAnchorId(title: string) {
  return `training-section-${title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "")}`;
}

export function renderTrainingSection(title: string, children: VNodeChild[]) {
  return h("fieldset", { id: sectionAnchorId(title), class: "training-section anima-section" }, [
    h("legend", title),
    ...children,
  ]);
}

export function renderTrainingSectionSpec<TForm extends TrainingFormState>(form: TForm, section: TrainingSectionSpec<TForm>) {
  if (section.hidden || !matchesVisibilityRule(form, section.visibleWhen)) {
    return null;
  }
  return renderTrainingSection(
    section.title,
    section.fields.map((item) => renderTrainingSectionItem(form, item)),
  );
}

export function renderTrainingSchemaSections<TForm extends TrainingFormState>(
  form: TForm,
  sections: TrainingSectionSpec<TForm>[],
) {
  return sections.map((section) => renderTrainingSectionSpec(form, section));
}

export function renderTrainingWorkbench(formPanel: VNodeChild[], previewPanel: VNodeChild[]) {
  return h("section", { class: "training-workbench anima-workbench" }, [
    h("div", { class: "training-form-panel anima-form-panel" }, formPanel),
    h("aside", { class: "training-preview-panel anima-preview-panel" }, previewPanel),
  ]);
}

export function renderParameterPreview(code: string, id = "training-preview-code") {
  return h("div", { class: "training-preview-card anima-preview-card" }, [
    h("h2", "Parameter Preview"),
    h("pre", { id, class: "training-preview-code anima-preview-code" }, code),
  ]);
}

export function renderRunControls(actions: RunControl[], status = "") {
  return h("div", { class: "training-preview-card anima-preview-card" }, [
    h("h2", "Run Controls"),
    h(
      "div",
      { class: "training-actions anima-actions" },
      actions.map((action) =>
        h(
          "button",
          {
            type: "button",
            class: action.primary ? "primary" : "",
            onClick: action.onClick,
          },
          action.label,
        ),
      ),
    ),
    status ? h("p", { class: "training-status anima-status" }, status) : null,
  ]);
}

export function previewToml(values: Record<string, unknown>): string {
  return Object.entries(values)
    .filter(([, value]) => value !== "")
    .map(([key, value]) => `${key} = ${tomlValue(value)}`)
    .join("\n");
}

export function tomlValue(value: unknown): string {
  if (typeof value === "boolean") {
    return value ? "true" : "false";
  }
  if (typeof value === "number") {
    return String(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map((item) => tomlValue(item)).join(", ")}]`;
  }
  return `"${String(value).replaceAll("\\", "\\\\").replaceAll('"', '\\"').replaceAll("\n", "\\n")}"`;
}

function renderFieldDescription(description?: string) {
  return description ? h("small", { class: "training-field-description" }, description) : null;
}

function renderTrainingSectionItem<TForm extends TrainingFormState>(form: TForm, item: TrainingSectionItem<TForm>) {
  if (item.hidden || !matchesVisibilityRule(form, item.visibleWhen)) {
    return null;
  }
  if (item.kind === "row") {
    return renderTrainingFieldRow(renderTrainingFields(form, item.fields));
  }
  return renderTrainingField(form, item);
}

export function matchesVisibilityRule<TForm extends TrainingFormState>(
  form: TForm,
  rule?: TrainingVisibilityRule<TForm>,
) {
  if (!rule) {
    return true;
  }
  if (typeof rule === "function") {
    return rule(form);
  }
  const value = form[rule.key];
  if ("equals" in rule) {
    return value === rule.equals;
  }
  if ("notEquals" in rule) {
    return value !== rule.notEquals;
  }
  if ("truthy" in rule) {
    return Boolean(value) === rule.truthy;
  }
  return true;
}

function renderSliderField<TForm extends TrainingFormState>(
  form: TForm,
  field: Extract<TrainingFieldSpec<TForm>, { kind: "number" }>,
) {
  const value = Number(form[field.key] ?? 0);
  return h("label", { class: "training-field anima-field training-slider-field" }, [
    h("span", field.label),
    h("div", { class: "training-slider-field__control" }, [
      h("input", {
        id: field.id,
        type: "range",
        min: field.min ?? 0,
        max: field.max ?? 12,
        step: field.step ?? 1,
        disabled: field.disabled,
        value,
        "data-training-role": field.role,
        onInput: (event: Event) => {
          form[field.key] = Number((event.target as HTMLInputElement).value) as TForm[keyof TForm & string];
        },
      }),
      h("output", { id: `${field.id}-value`, for: field.id }, String(value)),
    ]),
    renderFieldDescription(field.description),
  ]);
}

function renderTextInput<TForm extends TrainingFormState>(
  form: TForm,
  field: Extract<TrainingFieldSpec<TForm>, { kind: "text" }>,
) {
  const input = h("input", {
    id: field.id,
    disabled: field.disabled,
    value: String(form[field.key] ?? ""),
    placeholder: field.placeholder ?? "",
    "data-training-role": field.role,
    onInput: (event: Event) => {
      form[field.key] = (event.target as HTMLInputElement).value as TForm[keyof TForm & string];
    },
  });

  if (field.role !== "file" && field.role !== "folder") {
    return input;
  }

  return h("div", { class: "training-path-field" }, [
    input,
    h(
      "button",
      {
        type: "button",
        class: "training-path-field__browse",
        disabled: field.disabled,
        title: `${field.role === "folder" ? "Folder" : "File"} picker integration is pending`,
        onClick: () => {
          window.dispatchEvent(
            new CustomEvent("sd-training-path-browse", {
              detail: { key: field.key, role: field.role, id: field.id },
            }),
          );
        },
      },
      "Browse",
    ),
  ]);
}

function renderTrainingTableField<TForm extends TrainingFormState>(
  form: TForm,
  field: Extract<TrainingFieldSpec<TForm>, { kind: "table" }>,
) {
  const values = Array.isArray(form[field.key]) ? (form[field.key] as string[]) : [];

  function update(next: string[]) {
    form[field.key] = next as TForm[keyof TForm & string];
  }

  return h("div", { id: field.id, class: "training-field anima-field training-table-field" }, [
    h("span", field.label),
    h(
      "div",
      { class: "training-table-field__rows" },
      values.map((value, index) =>
        h("div", { class: "training-table-field__row" }, [
          h("input", {
            id: `${field.id}-${index}`,
            disabled: field.disabled,
            value,
            onInput: (event: Event) => {
              const next = [...values];
              next[index] = (event.target as HTMLInputElement).value;
              update(next);
            },
          }),
          h(
            "button",
            {
              type: "button",
              disabled: field.disabled,
              onClick: () => update(values.filter((_, itemIndex) => itemIndex !== index)),
            },
            "Remove",
          ),
        ]),
      ),
    ),
    h(
      "button",
      {
        type: "button",
        class: "training-table-field__add",
        disabled: field.disabled,
        onClick: () => update([...values, ""]),
      },
      field.addLabel ?? "Add Row",
    ),
    renderFieldDescription(field.description),
  ]);
}
